static std::vector<uint8_t> directRaster(const SessionRenderItem& item,Cache& cache){std::vector<uint8_t> output(480*320*4);auto copy=[&](const auto& r){for(int y=0;y<r.bounds.height;++y)for(int x=0;x<r.bounds.width;++x)for(int k=0;k<4;++k)output[((y+r.bounds.y)*480+x+r.bounds.x)*4+k]=r.rgba[(y*r.bounds.width+x)*4+k];};if(auto* d=std::get_if<DrawSprite>(&item)){SpriteRasterInput in;in.columns=d->cols;in.rows=d->rows;in.tile=d->frame;in.position=d->position;in.scale=d->scale;in.rotation=d->rotation;in.alpha=d->alpha;in.blend=d->blend;copy(rasterizeSprite(in,cache.get(d->tile).view()));}else{auto& m=std::get<TrailMesh>(item);copy(rasterizeTrail(m,cache.get(m.tile).view(true)));}return output;}
